SELECT p.id AS position_id, p.symbol, p.entry_price, MAX(c.high_price) AS max_high, MIN(c.low_price) AS min_low, COUNT(*) AS n_1m FROM paper_position p JOIN candle c ON c.symbol=p.symbol AND c.interval_code='1m' AND c.open_time >= p.opened_at - INTERVAL 1 MINUTE AND c.open_time <= p.closed_at WHERE p.id IN (104,101,96,91,82,78) GROUP BY p.id, p.symbol, p.entry_price ORDER BY p.id;